```typescript
// lib/hooks/useComparison.ts
import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface ComparisonStore {
  properties: Property[];
  addProperty: (property: Property) => void;
  removeProperty: (propertyId: string) => void;
  clearAll: () => void;
}

export const useComparison = create<ComparisonStore>(
  persist(
    (set) => ({
      properties: [],
      addProperty: (property) => set((state) => {
        if (state.properties.length >= 3) return state;
        if (state.properties.some(p => p.id === property.id)) return state;
        return { properties: [...state.properties, property] };
      }),
      removeProperty: (propertyId) => set((state) => ({
        properties: state.properties.filter(p => p.id !== propertyId)
      })),
      clearAll: () => set({ properties: [] }),
    }),
    { name: 'property-comparison' }
  )
);
```
