// lib/auth.ts
export function hasRole(user: User, role: 'admin' | 'superadmin'): boolean {
  return user?.role === role;
}

export async function requireRole(req: NextRequest, role: 'admin' | 'superadmin') {
  const user = await getUser(req);
  if (!user || !hasRole(user, role)) {
    return new Response(JSON.stringify({ error: 'Unauthorized' }), {
      status: 403,
      headers: { 'Content-Type': 'application/json' },
    });
  }
  return user;
}
```

