2. Implement GET /api/listings endpoint:
```typescript
// app/api/listings/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { listingQuerySchema } from '@shared/types';

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const parsed = listingQuerySchema.parse(Object.fromEntries(searchParams));

    const { type, city, price_min, price_max, bedrooms, lang, page, limit, sort } = parsed;

    // Build filter conditions
    const where: any = {};
    if (type) where.type = type;
    if (city) where.location = { city };
    if (bedrooms) where.bedrooms = { gte: bedrooms };
    if (price_min) where.price = { ...where.price, gte: price_min };
    if (price_max) where.price = { ...where.price, lte: price_max };

    // Build sort options
    const orderBy: any = {};
    switch (sort) {
      case 'newest': orderBy.createdAt = 'desc'; break;
      case 'price_asc': orderBy.price = 'asc'; break;
      case 'price_desc': orderBy.price = 'desc'; break;
      case 'size_asc': orderBy.size = 'asc'; break;
      case 'size_desc': orderBy.size = 'desc'; break;
    }

    // Execute query with pagination
    const [listings, total] = await Promise.all([
      prisma.listing.findMany({
        where,
        orderBy,
        skip: (page - 1) * limit,
        take: limit,
        include: {
          agent: true,
          category: true,
          location: true,
        },
      }),
      prisma.listing.count({ where }),
    ]);

    // Transform data for response (handle multilingual content)
    const formattedListings = listings.map(listing => ({
      ...listing,
      title: listing.title[lang] || listing.title.en,
      description: listing.description[lang] || listing.description.en,
      agent: {
        ...listing.agent,
        bio: listing.agent.bio[lang] || listing.agent.bio.en,
      },
      category: {
        ...listing.category,
        name: listing.category.name[lang] || listing.category.name.en,
      },
      location: {
        ...listing.location,
        name: listing.location.name[lang] || listing.location.name.en,
      },
    }));

    // Set cache headers
    const headers = new Headers();
    headers.set('Cache-Control', 'public, s-maxage=60, stale-while-revalidate=300');

    return NextResponse.json(
      { 
        listings: formattedListings, 
        pagination: {
          total,
          pages: Math.ceil(total / limit),
          page,
          limit,
        }
      },
      { headers }
    );
  } catch (error) {
    console.error('Error fetching listings:', error);
    return NextResponse.json({ error: 'Failed to fetch listings' }, { status: 500 });
  }
}
```

