import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { z } from 'zod';

const querySchema = z.object({
  lang: z.enum(['en', 'bg', 'ru']).default('en'),
});

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const { lang } = querySchema.parse(Object.fromEntries(searchParams));

    const agents = await prisma.agent.findMany({
      include: {
        _count: {
          select: { listings: true }
        }
      }
    });

    const formattedAgents = agents.map(agent => ({
      id: agent.id,
      name: agent.name,
      email: agent.email,
      phone: agent.phone,
      photo: agent.photo,
      bio: agent.bio[lang] || agent.bio.en,
      listingCount: agent._count.listings,
    }));

    const headers = new Headers();
    headers.set('Cache-Control', 'public, s-maxage=300, stale-while-revalidate=600');

    return NextResponse.json({ agents: formattedAgents }, { headers });
  } catch (error) {
    console.error('Error fetching agents:', error);
    return NextResponse.json({ error: 'Failed to fetch agents' }, { status: 500 });
