3. Implement bookings system:
```typescript
// app/api/bookings/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getUser, requireRole } from '@/lib/auth';
import { sendEmail } from '@/lib/email';
import { z } from 'zod';

const bookingSchema = z.object({
  listingId: z.string(),
  date: z.string().datetime(),
  name: z.string().min(2),
  email: z.string().email(),
  phone: z.string(),
  message: z.string().optional(),
});

export async function POST(request: NextRequest) {
  try {
    const data = bookingSchema.parse(await request.json());

    // Get user if authenticated (optional)
    const user = await getUser(request);

    // Create booking
    const booking = await prisma.booking.create({
      data: {
        ...data,
        userId: user?.id, // Link to user if authenticated
        status: 'pending',
      },
      include: {
        listing: {
          include: { agent: true }
        },
      },
    });

    // Send email notifications
    await Promise.all([
      // Send confirmation to visitor
      sendEmail({
        to: data.email,
        subject: 'Your Property Visit Request',
        template: 'booking-confirmation',
        data: { booking },
      }),

      // Send notification to agent
      sendEmail({
        to: booking.listing.agent.email,
        subject: 'New Property Visit Request',
        template: 'booking-notification-agent',
        data: { booking },
      }),
    ]);

    return NextResponse.json({ booking });
  } catch (error) {
    console.error('Error creating booking:', error);
    if (error instanceof z.ZodError) {
      return NextResponse.json({ error: error.errors }, { status: 400 });
    }
    return NextResponse.json({ error: 'Failed to create booking' }, { status: 500 });
  }
}

export async function GET(request: NextRequest) {
  const user = await getUser(request);

  // Check if admin or regular user
  const isAdmin = user?.role === 'admin' || user?.role === 'superadmin';

  try {
    if (isAdmin) {
      // Admins can see all bookings
      const bookings = await prisma.booking.findMany({
        include: {
          listing: true,
          user: true,
        },
        orderBy: { createdAt: 'desc' },
      });
      return NextResponse.json({ bookings });
    } else if (user) {
      // Regular users see only their bookings
      const bookings = await prisma.booking.findMany({
        where: { userId: user.id },
        include: { listing: true },
        orderBy: { createdAt: 'desc' },
      });
      return NextResponse.json({ bookings });
    } else {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }
  } catch (error) {
    console.error('Error fetching bookings:', error);
    return NextResponse.json({ error: 'Failed to fetch bookings' }, { status: 500 });
  }
}
```

