4. Implement secure upload endpoint:
```typescript
// app/api/upload/images/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { generateUploadSignature } from '@/lib/cloudinary';
import { requireRole } from '@/lib/auth';
import { z } from 'zod';

const uploadRequestSchema = z.object({
  folder: z.enum(['properties', 'agents']),
  filename: z.string(),
});

export async function POST(request: NextRequest) {
  // Only admins can upload files
  const user = await requireRole(request, 'admin');
  if (!user) return;

  try {
    const data = uploadRequestSchema.parse(await request.json());

    // Generate a unique public ID based on folder and filename
    const publicId = `${data.folder}/${Date.now()}-${data.filename.replace(/\.[^/.]+$/, '')}`;

    // Generate upload signature for direct frontend upload
    const uploadParams = generateUploadSignature(data.folder, publicId);

    return NextResponse.json({
      ...uploadParams,
      publicId,
      folder: data.folder,
    });
  } catch (error) {
    console.error('Error generating upload signature:', error);
    if (error instanceof z.ZodError) {
      return NextResponse.json({ error: error.errors }, { status: 400 });
    }
    return NextResponse.json({ error: 'Failed to generate upload signature' }, { status: 500 });
  }
}
```

