// lib/email.ts
import { Resend } from 'resend';
import { renderToString } from 'react-dom/server';
import * as templates from '@/components/email-templates';

const resend = new Resend(process.env.RESEND_API_KEY);

type TemplateNames = keyof typeof templates;
type TemplateProps = {
  [K in TemplateNames]: React.ComponentProps<typeof templates[K]>;
};

type SendEmailOptions<T extends TemplateNames> = {
  to: string;
  subject: string;
  template: T;
  data: TemplateProps[T];
  from?: string;
  replyTo?: string;
};

export async function sendEmail<T extends TemplateNames>({
  to,
  subject,
  template,
  data,
  from = process.env.NO_REPLY_EMAIL,
  replyTo,
}: SendEmailOptions<T>) {
  const Template = templates[template];
  const html = renderToString(Template(data as any));

  return resend.emails.send({
    from,
    to,
    subject,
    html,
    ...(replyTo && { reply_to: replyTo }),
  });
}
```

