import { prisma } from '@/lib/prisma';
import { sendEmail } from '@/lib/email';

export async function processAlerts() {
  try {
    // Get all active alerts
    const alerts = await prisma.alert.findMany({
      where: { status: 'active' },
    });

    for (const alert of alerts) {
      // Find matching new listings based on alert criteria
      const matchingListings = await prisma.listing.findMany({
        where: {
          createdAt: { gte: alert.lastProcessedAt || new Date(0) },
          ...(alert.criteria.type && { type: alert.criteria.type }),
          ...(alert.criteria.city && { location: { city: alert.criteria.city } }),
          ...(alert.criteria.price_min && { price: { gte: alert.criteria.price_min } }),
          ...(alert.criteria.price_max && { price: { lte: alert.criteria.price_max } }),
          ...(alert.criteria.bedrooms && { bedrooms: { gte: alert.criteria.bedrooms } }),
        },
        take: 10,
      });

      if (matchingListings.length > 0) {
        // Send alert email
        await sendEmail({
          to: alert.email,
          subject: 'New Properties Matching Your Search',
          template: 'alert-notification',
          data: {
            name: alert.name,
            listings: matchingListings,
            alertId: alert.id,
          },
        });

        // Update last processed timestamp
        await prisma.alert.update({
          where: { id: alert.id },
          data: { lastProcessedAt: new Date() },
        });
      }
    }

    console.log('Alert processing completed');
  } catch (error) {
    console.error('Error processing alerts:', error);
  }
}
