import CreateListingButton from '@/components/admin/CreateListingButton';

export default async function ListingsPage({
  searchParams,
}: {
  searchParams: { page?: string; search?: string; status?: string };
}) {
  const page = Number(searchParams.page) || 1;
  const limit = 10;
  const search = searchParams.search || '';
  const status = searchParams.status || undefined;

  // Build filter conditions
  const where: any = {};
  if (search) {
    where.OR = [
      { title: { path: ['en'], string_contains: search, mode: 'insensitive' } },
      { title: { path: ['bg'], string_contains: search, mode: 'insensitive' } },
      { title: { path: ['ru'], string_contains: search, mode: 'insensitive' } },
    ];
  }
  if (status) {
    where.status = status;
  }

  // Fetch listings with pagination
  const [listings, total] = await Promise.all([
    prisma.listing.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      skip: (page - 1) * limit,
      take: limit,
      include: { agent: true, category: true, location: true },
    }),
    prisma.listing.count({ where }),
  ]);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold">Listings</h1>
        <CreateListingButton />
      </div>

      <ListingsTable 
        listings={listings} 
        pagination={{
          total,
          pages: Math.ceil(total / limit),
          page,
          limit,
        }}
      />
    </div>
  );
}
