1. Implement rate limiting middleware:
```typescript
// middleware/rate-limit.ts
import { NextRequest, NextResponse } from 'next/server';
import { Redis } from '@upstash/redis';

const redis = new Redis({
  url: process.env.UPSTASH_REDIS_URL,
  token: process.env.UPSTASH_REDIS_TOKEN,
});

type RateLimitOptions = {
  limit: number;
  window: number; // in seconds
};

export async function rateLimit(
  request: NextRequest,
  options: RateLimitOptions = { limit: 10, window: 60 }
) {
  const ip = request.ip || 'anonymous';
  const key = `rate-limit:${ip}:${request.nextUrl.pathname}`;

  // Get current count
  const count = await redis.get<number>(key) || 0;

  // Check if over limit
  if (count >= options.limit) {
    return NextResponse.json(
      { error: 'Too many requests' },
      { status: 429, headers: { 'Retry-After': options.window.toString() } }
    );
  }

  // Increment count and set expiry
  await redis.incr(key);
  await redis.expire(key, options.window);

  // Add rate limit headers
  const response = NextResponse.next();
  response.headers.set('X-RateLimit-Limit', options.limit.toString());
  response.headers.set('X-RateLimit-Remaining', (options.limit - count - 1).toString());

  return response;
}
