// lib/db-helpers.ts
import { Prisma } from '@prisma/client';

export function optimizeListingQuery(query: any) {
  // Add necessary includes based on query parameters
  const includes: Prisma.ListingInclude = {};

  if (query.includeAgent) {
    includes.agent = true;
  }

  if (query.includeCategory) {
    includes.category = true;
  }

  if (query.includeLocation) {
    includes.location = true;
  }

  // Add selective fields if specified
  const select: Prisma.ListingSelect | undefined = query.fields
    ? query.fields.split(',').reduce((acc: any, field: string) => {
        acc[field.trim()] = true;
        return acc;
      }, {})
    : undefined;

  return { include: includes, select };
}
